    fun matchSubject(prompt: String): Pair<String, String>? {
        val lower = prompt.lowercase()
        return when {
            Regex("\\b(horse|stallion|pony|mustang|mare|colt|foal)\\b").containsMatchIn(lower) -> "HORSE" to "horse"
            Regex("\\b(cat|kitten|kitty|feline)\\b").containsMatchIn(lower) -> "CAT" to "cat"
            Regex("\\b(dog|puppy|hound|pup)\\b").containsMatchIn(lower) -> "DOG" to "dog"
            Regex("\\b(wolf|direwolf)\\b").containsMatchIn(lower) -> "WOLF" to "wolf"
            Regex("\\b(lion|tiger|panther|cheetah|leopard)\\b").containsMatchIn(lower) -> "LION" to "lion"
            Regex("\\b(eagle|hawk|falcon|bird|phoenix)\\b").containsMatchIn(lower) -> "EAGLE" to "eagle"
            Regex("\\b(dragon|wyvern)\\b").containsMatchIn(lower) -> "DRAGON" to "dragon"
            Regex("\\b(tree|forest|pine|oak|woods)\\b").containsMatchIn(lower) -> "TREE" to "tree"
            Regex("\\b(flower|rose|blossom|lotus|tulip|sunflower)\\b").containsMatchIn(lower) -> "FLOWER" to "flower"
            Regex("\\b(car|automobile|vehicle|sedan|racecar)\\b").containsMatchIn(lower) -> "CAR" to "car"
            Regex("\\b(rocket|spaceship|shuttle|spacecraft)\\b").containsMatchIn(lower) -> "ROCKET" to "rocket"
            Regex("\\b(robot|android|cyborg|bot|mech)\\b").containsMatchIn(lower) -> "ROBOT" to "robot"
            Regex("\\b(sword|blade|dagger|katana|saber)\\b").containsMatchIn(lower) -> "SWORD" to "sword"
            Regex("\\b(castle|fortress|palace|tower)\\b").containsMatchIn(lower) -> "CASTLE" to "castle"
            Regex("\\b(heart|love|valentine)\\b").containsMatchIn(lower) -> "HEART" to "heart"
            Regex("\\b(star|stars|constellation)\\b").containsMatchIn(lower) -> "STAR" to "star"
            Regex("\\b(crown|king|queen|royalty)\\b").containsMatchIn(lower) -> "CROWN" to "crown"
            Regex("\\b(shield|armor|defense)\\b").containsMatchIn(lower) -> "SHIELD" to "shield"
            Regex("\\b(skull|skeleton|bones)\\b").containsMatchIn(lower) -> "SKULL" to "skull"
            Regex("\\b(guitar|music|instrument|song)\\b").containsMatchIn(lower) -> "GUITAR" to "guitar"
            Regex("\\b(coffee|tea|cup|mug|espresso)\\b").containsMatchIn(lower) -> "COFFEE" to "coffee"
            Regex("\\b(book|reading|novel|library)\\b").containsMatchIn(lower) -> "BOOK" to "book"
            Regex("\\b(camera|photo|photography)\\b").containsMatchIn(lower) -> "CAMERA" to "camera"
            Regex("\\b(fish|clownfish|shark|dolphin)\\b").containsMatchIn(lower) -> "FISH" to "fish"
            Regex("\\b(airplane|aeroplane|plane|jet|flight)\\b").containsMatchIn(lower) -> "AIRPLANE" to "airplane"
            Regex("\\b(boat|ship|sailboat|yacht)\\b").containsMatchIn(lower) -> "BOAT" to "boat"
            Regex("\\b(flame|fire|bonfire|blaze)\\b").containsMatchIn(lower) -> "FLAME" to "flame"
            Regex("\\b(sun|sunshine|sunny)\\b").containsMatchIn(lower) -> "SUN" to "sun"
            Regex("\\b(moon|lunar|crescent)\\b").containsMatchIn(lower) -> "MOON" to "moon"
            Regex("\\b(butterfly|moth)\\b").containsMatchIn(lower) -> "BUTTERFLY" to "butterfly"
            Regex("\\b(house|home|cottage|cabin)\\b").containsMatchIn(lower) -> "HOUSE" to "house"
            Regex("\\b(person|man|woman|human|figure|runner)\\b").containsMatchIn(lower) -> "PERSON" to "person"
            else -> null
        }
    }
